PHASES = [
    (0, 9, "Childhood", 1.15),
    (9, 32, "Adolescence", 1.25),
    (32, 66, "Adult", 1.00),
    (66, 83, "Early Aging", 0.75),
    (83, 200, "Late Aging", 0.55),
]

REPORT_DIR = os.path.join(os.path.expanduser("~"), "reports")
os.makedirs(REPORT_DIR, exist_ok=True)

def clear_report_dir():
    if os.path.isdir(REPORT_DIR):
        for name in os.listdir(REPORT_DIR):
            path = os.path.join(REPORT_DIR, name)
            try:
                if os.path.isfile(path):
                    os.remove(path)
            except Exception:
                pass

def get_phase(age):
    for lo, hi, name, scale in PHASES:
        if lo <= age < hi:
            return name, scale
    return "Late Aging", 0.55

def parse_prompt(text):
    text = text.lower()
    age, ph, horm, id_flag = 32.0, 7.4, 1.0, 0
    ca, cyto = 1.2, 15.0
    patterns = {
        "age": r'(age|years|yrs|old)\s*[:=]?\s*([-+]?\d*\.?\d+)',
        "ph": r'(ph|acidity|alk|alkalinity)\s*[:=]?\s*([-+]?\d*\.?\d+)',
        "horm": r'(hormone|horm|thyroid|sex)\s*[:=]?\s*([-+]?\d*\.?\d+)',
        "ca": r'(calcium|ca|ion|ca2)\s*[:=]?\s*([-+]?\d*\.?\d+)',
        "cyto": r'(cytokine|cyto|il6|tnf|inflammation)\s*[:=]?\s*([-+]?\d*\.?\d+)',
    }
    for key, pat in patterns.items():
        m = re.search(pat, text)
        if m:
            val = float(m.group(2).replace(",", "."))
            if key == "age": age = val
            elif key == "ph": ph = val
            elif key == "horm": horm = val
            elif key == "ca": ca = val
            elif key == "cyto": cyto = val
    if re.search(r'(disabled|id)\s*(true|yes|1)', text):
        id_flag = 1
    return age, ph, horm, id_flag, ca, cyto

def myelin_metrics(age, ph, horm, id_flag, ca, cyto, mode="sqrt"):
    peak, base = 35.0, 150.0
    age_factor = math.exp(-0.5 * ((age - peak) / 20.0) ** 2)
    ph_factor = 1.0 if 7.1 <= ph <= 7.5 else 0.55
    horm_factor = max(0.4, horm)
    id_penalty = 0.65 if id_flag else 1.0
    ca_penalty = max(0.4, 1.0 - 0.25 * abs(ca - 1.2))
    cyto_penalty = max(0.3, 1.0 - (cyto / 100.0))
    thickness = base * age_factor * ph_factor * horm_factor * id_penalty * ca_penalty * cyto_penalty
    delta = thickness - 120.0
    g_ratio = max(0.55, min(0.95, 0.72 + (0.06 if id_flag else 0.0) - 0.08 * (delta / 50.0)))
    if mode == "linear":
        # Linear myelinated scaling (CV ∝ diameter proxy)
        vel = 0.12 * thickness * (1.0 / max(g_ratio, 0.5))
    else:
        # Original square-root (unmyelinated-like) scaling
        vel = 4.5 * 1.8 * (1.0 / g_ratio) * math.sqrt(max(thickness, 1.0) / 100.0)
    return thickness, delta, g_ratio, vel

def generate_discharge_summary(data):
    age = data['age']
    sex = data.get('sex', 'unspecified')
    thyroid = data.get('thyroid', 'euthyroid')
    symptom = data.get('symptom', 'None')
    myelination = data.get('myelination', 'Age-appropriate')
    inflammation = data.get('inflammation', 'Low')
    cognitive = data.get('cognitive', 'Intact')
    phase = data['phase']
    cyto = data['cyto']
    ca = data['ca']
    thick = data['thick']
    delta = data['delta']
    g = data['g']
    vel = data['vel']
    thickness_desc = "about average for the reference peak" if abs(delta) < 15 else ("thinner than the reference peak" if delta < 0 else "thicker than the reference peak")
    speed_desc = "within a typical range" if 4 < vel < 20 else ("on the slower side" if vel <= 4 else "on the faster side")
    inflam_desc = "low and not a major concern" if inflammation in ("None", "Low") else "elevated and something to keep an eye on"
    myelin_map = {
        "Age-appropriate": "in line with what is expected for your age",
        "Delayed": "developing more slowly than usual",
        "Hypomyelination": "thinner than expected overall",
    }
    myelin_desc = myelin_map.get(myelination, myelination.lower())
    symptom_phrase = "no specific symptoms were reported" if symptom == "None" else f"the main concern noted was {symptom.lower()}"
    summary = (
        f"Discharge Summary (in everyday language): You are a {age:.0f}-year-old {sex.lower()} "
        f"with {thyroid.lower()} thyroid function. On review, {symptom_phrase}, "
        f"and your thinking and memory ability is described as {cognitive.lower()}. "
        f"The protective myelin coating around your nerve fibers is currently {myelin_desc}. "
        f"Inflammation is {inflam_desc} (cytokine level about {cyto:.0f} pg/mL). "
        f"Calcium is at {ca:.2f} mmol/L. "
        f"The measured myelin thickness is approximately {thick:.0f} nanometers, which is {thickness_desc}. "
        f"Nerve signals are traveling at about {vel:.1f} meters per second ({speed_desc}), "
        f"and the coating efficiency (g-ratio) is {g:.2f}. "
        f"These findings place you in the {phase.lower()} stage of life, when the myelin coating "
        f"naturally peaks in adulthood and then gradually changes with age. "
        f"Overall, the results are consistent with expected changes for the {phase.lower()} period. "
        f"Educational nutrient ideas for this phase (illustrative only, not a prescription): "
    )
    nutrient_tips = {
        "Childhood": "Vitamin D 600 IU, omega-3 (DHA) 100–200 mg, iron-rich foods, and choline from eggs or beans.",
        "Adolescence": "Vitamin D 600–1000 IU, omega-3 250–500 mg DHA+EPA, B-vitamins (especially B12), and magnesium 200–300 mg.",
        "Adult": "Vitamin D 1000–2000 IU, omega-3 500–1000 mg, magnesium 300–400 mg, and a B-complex.",
        "Early Aging": "Vitamin D 2000 IU, omega-3 1000 mg, vitamin B12 500–1000 mcg, and magnesium 300–400 mg.",
        "Late Aging": "Vitamin D 2000 IU, omega-3 1000 mg, B12 1000 mcg, and consider a senior multivitamin with lutein.",
    }
    tip = nutrient_tips.get(phase, nutrient_tips["Adult"])
    summary += tip + " "
    summary += (
        f"These quantities are general educational examples only. "
        f"Talk with a qualified clinician before starting any supplement. "
        f"We also recommend regular activity, good sleep, and managing inflammation if it rises. "
        f"This educational analysis is not a substitute for personal medical advice from a qualified doctor."
    )
    return summary

def generate_charts(data):
    if not HAS_MPL:
        return []
    clear_report_dir()
    age = data['age']
    ph = data['ph']
    horm = data['horm']
    id_flag = data['id_flag']
    ca = data['ca']
    cyto = data['cyto']
    paths = []

    # 1. Thickness with differentially shaded areas (enhanced)
    ages = list(range(1, 101, 2))
    thicks = [myelin_metrics(a, ph, horm, id_flag, ca, cyto)[0] for a in ages]
    fig, ax = plt.subplots(figsize=(8, 4.5))
    ax.plot(ages, thicks, color="#0d6efd", linewidth=2.5, label="Thickness")
    ax.axvline(age, color="red", linestyle="--", linewidth=1.5, label=f"Age {age:.0f}")
    ax.axhline(100, color="gray", linestyle=":", alpha=0.7)
    ax.fill_between(ages, thicks, 100, where=[t >= 120 for t in thicks], color="#198754", alpha=0.35, label="High")
    ax.fill_between(ages, thicks, 100, where=[(t >= 80) and (t < 120) for t in thicks], color="#ffc107", alpha=0.3, label="Normal")
    ax.fill_between(ages, thicks, 100, where=[t < 80 for t in thicks], color="#dc3545", alpha=0.3, label="Low")
    ax.set_xlabel("Age (years)")
    ax.set_ylabel("Myelin Thickness (nm)")
    ax.set_title("Thickness Lifespan — Differentially Shaded Regions")
    ax.legend(loc="upper right", fontsize=8)
    ax.grid(True, alpha=0.3)
    p1 = os.path.join(REPORT_DIR, "Featured_thickness_sweep.png")
    fig.tight_layout()
    fig.savefig(p1, dpi=120)
    plt.close(fig)
    paths.append(p1)

    # 2. Dual-sphere Venn-style 3D mapping (nervous area as coordinate frame)
    fig = plt.figure(figsize=(7, 6))
    ax = fig.add_subplot(111, projection="3d")
    u = [i * math.pi / 18 for i in range(19)]
    v = [i * 2 * math.pi / 28 for i in range(29)]
    # Sphere 1: nervous-system frame
    for uu in u[::2]:
        xs = [math.sin(uu)*math.cos(vv) for vv in v]
        ys = [math.sin(uu)*math.sin(vv) for vv in v]
        zs = [math.cos(uu) for vv in v]
        ax.plot(xs, ys, zs, color="#0d6efd", alpha=0.35, linewidth=0.7)
    # Sphere 2: translated / overlapping (Venn)
    offset = 0.9
    for uu in u[::2]:
        xs = [offset + math.sin(uu)*math.cos(vv)*0.85 for vv in v]
        ys = [math.sin(uu)*math.sin(vv)*0.85 for vv in v]
        zs = [math.cos(uu)*0.85 for vv in v]
        ax.plot(xs, ys, zs, color="#fd7e14", alpha=0.35, linewidth=0.7)
    # Connected myelin sheath vertices along nerve path inside the frame
    n_sheaths = 10
    nerve_x, nerve_y, nerve_z = [], [], []
    for i in range(n_sheaths):
        t = i / max(n_sheaths-1, 1)
        theta = 0.4 + t * 2.0
        phi = t * 5.0
        r = 0.7 + 0.15 * math.sin(t * math.pi * 2)
        nerve_x.append(r * math.sin(theta) * math.cos(phi))
        nerve_y.append(r * math.sin(theta) * math.sin(phi))
        nerve_z.append(r * math.cos(theta))
    ax.plot(nerve_x, nerve_y, nerve_z, color="#198754", linewidth=2.8, label="Nerve + myelin")
    ax.scatter(nerve_x, nerve_y, nerve_z, c="#dc3545", s=50, depthshade=True)
    # Current focus
    idx = min(int(age / 100.0 * (n_sheaths-1)), n_sheaths-1)
    ax.scatter([nerve_x[idx]], [nerve_y[idx]], [nerve_z[idx]], c="#ffc107", s=140, edgecolors="black", linewidth=0.8, label="Current")
    ax.set_title("3D Dual-Sphere Venn Mapping\n(Nervous area coordinate frame + connected myelin)")
    ax.legend(fontsize=7)
    try:
        ax.set_box_aspect([1,1,1])
    except Exception:
        pass
    p2 = os.path.join(REPORT_DIR, "Featured_sphere.png")
    fig.tight_layout()
    fig.savefig(p2, dpi=120)
    plt.close(fig)
    paths.append(p2)

    # 3. Heatmap (cytokine × calcium effect on thickness)
    cyto_vals = [5, 15, 30, 60, 100]
    ca_vals = [0.9, 1.1, 1.2, 1.4, 1.6]
    heat = []
    for c in ca_vals:
        row = []
        for cy in cyto_vals:
            t, _, _, _ = myelin_metrics(age, ph, horm, id_flag, c, cy)
            row.append(t)
        heat.append(row)
    fig, ax = plt.subplots(figsize=(6, 5))
    im = ax.imshow(heat, cmap="RdYlBu_r", aspect="auto")
    ax.set_xticks(range(len(cyto_vals)))
    ax.set_xticklabels(cyto_vals)
    ax.set_yticks(range(len(ca_vals)))
    ax.set_yticklabels(ca_vals)
    ax.set_xlabel("Cytokines (pg/mL)")
    ax.set_ylabel("Calcium (mmol/L)")
    ax.set_title("Thickness Heatmap (current age)")
    plt.colorbar(im, ax=ax, label="Thickness (nm)")
    p3 = os.path.join(REPORT_DIR, "Featured_heatmap.png")
    fig.tight_layout()
    fig.savefig(p3, dpi=120)
    plt.close(fig)
    paths.append(p3)

    # 4. Histogram of thickness distribution across ages
    fig, ax = plt.subplots(figsize=(6, 4))
    ax.hist(thicks, bins=12, color="#0d6efd", edgecolor="white", alpha=0.8)
    ax.axvline(data.get('thick', thicks[len(thicks)//2]), color="red", linestyle="--", label="Current")
    ax.set_xlabel("Thickness (nm)")
    ax.set_ylabel("Frequency")
    ax.set_title("Thickness Distribution Histogram")
    ax.legend()
    p4 = os.path.join(REPORT_DIR, "Featured_histogram.png")
    fig.tight_layout()
    fig.savefig(p4, dpi=120)
    plt.close(fig)
    paths.append(p4)

    # 5. Simple phase tree diagram
    fig, ax = plt.subplots(figsize=(7, 4))
    ax.set_xlim(0, 10)
    ax.set_ylim(0, 6)
    ax.axis("off")
    phases = ["Childhood", "Adolescence", "Adult", "Early Aging", "Late Aging"]
    xs = [1, 3, 5, 7, 9]
    for i, (x, name) in enumerate(zip(xs, phases)):
        color = "#198754" if name == data.get("phase") else "#6c757d"
        ax.scatter([x], [3], s=800, c=color, zorder=3)
        ax.text(x, 3, name[:3], ha="center", va="center", color="white", fontsize=8, fontweight="bold")
        if i < len(xs)-1:
            ax.annotate("", xy=(xs[i+1]-0.4, 3), xytext=(x+0.4, 3),
                        arrowprops=dict(arrowstyle="->", color="#0d6efd", lw=1.5))
    ax.set_title("Phase Progression Tree")
    p5 = os.path.join(REPORT_DIR, "Featured_phase_tree.png")
    fig.tight_layout()
    fig.savefig(p5, dpi=120)
    plt.close(fig)
    paths.append(p5)

    # 6. Additional heatmap: Age × Cytokine
    age_vals = [10, 30, 50, 70, 90]
    cyto_vals2 = [10, 25, 50, 80, 120]
    heat2 = []
    for a in age_vals:
        row = []
        for cy in cyto_vals2:
            t, _, _, _ = myelin_metrics(a, ph, horm, id_flag, ca, cy)
            row.append(t)
        heat2.append(row)
    fig, ax = plt.subplots(figsize=(6, 5))
    im = ax.imshow(heat2, cmap="viridis", aspect="auto")
    ax.set_xticks(range(len(cyto_vals2)))
    ax.set_xticklabels(cyto_vals2)
    ax.set_yticks(range(len(age_vals)))
    ax.set_yticklabels(age_vals)
    ax.set_xlabel("Cytokines (pg/mL)")
    ax.set_ylabel("Age (years)")
    ax.set_title("Age × Cytokine Heatmap")
    plt.colorbar(im, ax=ax, label="Thickness (nm)")
    p6 = os.path.join(REPORT_DIR, "Featured_heatmap_age_cyto.png")
    fig.tight_layout()
    fig.savefig(p6, dpi=120)
    plt.close(fig)
    paths.append(p6)

    # 7. Phase-average bar graph
    phase_ages = {"Childhood": 5, "Adolescence": 20, "Adult": 45, "Early Aging": 75, "Late Aging": 90}
    phase_thicks = []
    phase_names = []
    for name, a in phase_ages.items():
        t, _, _, _ = myelin_metrics(a, ph, horm, id_flag, ca, cyto)
        phase_thicks.append(t)
        phase_names.append(name)
    fig, ax = plt.subplots(figsize=(7, 4))
    colors_bar = ["#198754" if n == data.get("phase") else "#0d6efd" for n in phase_names]
    ax.bar(phase_names, phase_thicks, color=colors_bar, edgecolor="white")
    ax.set_ylabel("Thickness (nm)")
    ax.set_title("Average Thickness by Life Phase")
    ax.tick_params(axis="x", rotation=15)
    p7 = os.path.join(REPORT_DIR, "Featured_phase_bars.png")
    fig.tight_layout()
    fig.savefig(p7, dpi=120)
    plt.close(fig)
    paths.append(p7)

    # 8. Velocity vs thickness scatter
    vels = [myelin_metrics(a, ph, horm, id_flag, ca, cyto)[3] for a in ages]
    fig, ax = plt.subplots(figsize=(6, 4.5))
    sc = ax.scatter(thicks, vels, c=ages, cmap="plasma", s=30)
    ax.set_xlabel("Thickness (nm)")
    ax.set_ylabel("Velocity (m/s)")
    ax.set_title("Velocity vs Thickness (colored by age)")
    plt.colorbar(sc, ax=ax, label="Age")
    p8 = os.path.join(REPORT_DIR, "Featured_velocity_scatter.png")
    fig.tight_layout()
    fig.savefig(p8, dpi=120)
    plt.close(fig)
    paths.append(p8)

    # 9. Model vs scaling laws (square-root + linear)
    vels_sqrt = [myelin_metrics(a, ph, horm, id_flag, ca, cyto, mode="sqrt")[3] for a in ages]
    vels_lin = [myelin_metrics(a, ph, horm, id_flag, ca, cyto, mode="linear")[3] for a in ages]
    scale = np.mean(np.array(vels_sqrt) / np.sqrt(np.maximum(thicks, 1)))
    sqrt_ref = scale * np.sqrt(np.maximum(thicks, 1))
    # Linear reference scaled to match mid-range
    lin_scale = np.mean(np.array(vels_lin) / np.maximum(thicks, 1))
    lin_ref = lin_scale * np.maximum(thicks, 1)
    fig, ax = plt.subplots(figsize=(8, 5))
    ax.scatter(thicks, vels_sqrt, c="#0d6efd", s=40, label="Model (square-root mode)", zorder=3)
    ax.plot(thicks, sqrt_ref, color="#dc3545", linewidth=2, label=r"$\sqrt{\mathrm{thickness}}$ reference")
    ax.plot(thicks, lin_ref, color="#198754", linewidth=2, linestyle="--", label="Linear (myelinated) reference")
    ax.set_xlabel("Thickness (nm)")
    ax.set_ylabel("Velocity (m/s)")
    ax.set_title("Velocity vs Thickness\nSquare-root vs Linear Myelinated Scaling")
    ax.legend(loc="upper left", fontsize=8)
    ax.grid(True, alpha=0.3)
    p9 = os.path.join(REPORT_DIR, "Featured_velocity_powerlaw.png")
    fig.tight_layout()
    fig.savefig(p9, dpi=120)
    plt.close(fig)
    paths.append(p9)

    return paths

def generate_pdf(data, summary, chart_paths=None):
    if not HAS_RL:
        return None
    pdf_path = os.path.join(REPORT_DIR, "Featured_discharge_summary.pdf")
    doc = SimpleDocTemplate(pdf_path, pagesize=letter, rightMargin=50, leftMargin=50, topMargin=50, bottomMargin=50)
    styles = getSampleStyleSheet()
    story = [
        Paragraph("Educational Myelin & Neuroinflammation Report", styles["Title"]),
        Spacer(1, 8),
        Paragraph("<b>Report Utility:</b> This PDF packages the plain-language discharge summary together with annotated charts. It is necessary as a single, shareable document that explains both the numeric findings and the purpose of each visual.", styles["Normal"]),
        Spacer(1, 8),
        Paragraph(summary, styles["Normal"]),
        Spacer(1, 12),
        Paragraph("<b>Supporting Charts</b>", styles["Heading2"]),
    ]
    if chart_paths:
        explanations = {
            "Featured_thickness_sweep.png": "Utility: This lifespan thickness plot with multi-level shading (high/normal/low) lets you instantly see where myelin coating is robust or reduced relative to a reference baseline. It is necessary for visualizing age-related change and identifying periods of relative thinning that may warrant lifestyle attention.",
            "Featured_sphere.png": "Utility: The dual-sphere Venn-style mapping places the nervous-system coordinate frame and a translated state in the same view, with connected myelin-sheath vertices forming a representative nerve path. It is necessary for understanding how the current embedding sits inside (and can be translated within) the overall nervous geometry.",
            "Featured_heatmap.png": "Utility: The calcium-by-cytokine heatmap reveals interaction effects on thickness at the current age. It is necessary for exploring how inflammation and ionic balance jointly influence myelin support.",
            "Featured_histogram.png": "Utility: The histogram shows the spread of thickness values across the lifespan and marks the current reading. It is necessary for judging whether the present value is typical or an outlier within the modeled range.",
            "Featured_phase_tree.png": "Utility: The phase progression tree summarizes the major life-stage sequence and highlights the current epoch. It is necessary for quickly situating the analysis inside the broader developmental timeline.",
            "Featured_heatmap_age_cyto.png": "Utility: This second heatmap explores age-by-cytokine interactions. It is necessary for seeing how inflammatory load modulates thickness differently at different ages.",
            "Featured_phase_bars.png": "Utility: The bar chart compares representative thickness across life phases and highlights the current one. It is necessary for a compact phase-to-phase comparison.",
            "Featured_velocity_scatter.png": "Utility: The scatter relates nerve-signal velocity to thickness, colored by age. It is necessary for linking structural myelin measures to functional conduction speed.",
            "Featured_velocity_powerlaw.png": "Utility: Compares the model’s square-root velocity to both a pure square-root reference and a linear myelinated-style reference. It is necessary for seeing how the classic unmyelinated (√) versus myelinated (linear) scaling laws differ.",
        }
        for cp in chart_paths[:8]:
            if os.path.exists(cp) and cp.lower().endswith(".png"):
                name = os.path.basename(cp)
                story.append(Spacer(1, 8))
                story.append(Paragraph(f"<b>{name}</b>", styles["Heading3"]))
                expl = explanations.get(name, "Supporting visualization for the myelin analysis.")
                story.append(Paragraph(expl, styles["Normal"]))
                story.append(Spacer(1, 4))
                story.append(Image(cp, width=5.2*inch, height=2.8*inch))
    story.append(Spacer(1, 12))
    story.append(Paragraph("<i>Educational only — not medical advice or diagnosis.</i>", styles["Italic"]))
    doc.build(story)
    return pdf_path

def generate_notes(data, summary):
    notes_path = os.path.join(REPORT_DIR, "Featured_notes.txt")
    with open(notes_path, "w", encoding="utf-8") as f:
        f.write(f"Featured Notes — {datetime.now().strftime('%Y-%m-%d %H:%M')}\n\n")
        f.write("UTILITY: These notes consolidate the plain-language summary and raw metrics into a single portable text file. They are necessary for quick review, sharing, or archiving without opening the full PDF or image set.\n\n")
        f.write("G-RATIO OPTIMIZATION: The g-ratio (axon diameter / total fiber diameter) has a theoretical optimum near 0.6 in peripheral nerve and ~0.7–0.77 in the CNS. At this value conduction velocity is maximized for a given fiber diameter because it balances myelin thickness (which speeds saltatory conduction) against axon cross-section (which lowers axial resistance). The model keeps g-ratio in a realistic 0.55–0.95 band.\n\n")
        f.write(summary)
        f.write("\n\n--- Metrics ---\n")
        for k, v in data.items():
            if k not in ("nn",):
                f.write(f"{k}: {v}\n")
    return notes_path

